import { onDestroy } from 'svelte';

/**
 * Extensions catalog: fetches /extensions/index.json (same-origin static catalog)
 * and tracks install/update status for each available plugin.
 * 
 * Provisioning: files in ~/extensions/<id>/ (user/deploy script places them).
 * Discovery: this module reads index.json (regenerated by tools/extensions-sync.js).
 * Loading: unchanged — loader.fetchManifest + import(entry).
 * Enablement: mpu:v2:plugins records with source='catalog'.
 */

export interface CatalogEntry {
  id: string;
  name: string;
  version: string;
  manifestUrl: string;  // same-origin: /extensions/<id>/manifest.json
  icon?: string;
  description?: string;
  /** 'registry' — установлен tools/tessera-ext.cjs из реестра (sha256 сверен), 'local' — положен вручную. */
  origin: 'registry' | 'local';
}

export interface CatalogState {
  loading: boolean;
  error: string | null;
  entries: CatalogEntry[];
  /**
   * /extensions/policy.json (пишет deploy/install.sh). Только для UI: реальный запрет —
   * CSP script-src 'self' в nginx. Нет файла (dev, ручная установка) → разрешено.
   */
  allowRemotePlugins: boolean;
}

export interface CatalogStatus {
  status: 'not-installed' | 'installed' | 'update-available' | 'broken';
  installedVersion?: string;
  catalogVersion?: string;
}

let catalog = $state<CatalogState>({
  loading: false,
  error: null,
  entries: [],
  allowRemotePlugins: true,
});

const changeListeners = new Set<() => void>();

function emitChange(): void {
  for (const cb of Array.from(changeListeners)) {
    try {
      cb();
    } catch (e) {
      console.error('[extensions-catalog] change listener error', e);
    }
  }
}

async function fetchAllowRemotePlugins(): Promise<boolean> {
  try {
    const res = await fetch('/extensions/policy.json', { cache: 'no-store' });
    if (!res.ok) return true;
    const data = await res.json();
    return data?.allowRemotePlugins !== false;
  } catch {
    return true;
  }
}

async function refresh(): Promise<void> {
  if (catalog.loading) return;

  catalog = { ...catalog, loading: true, error: null };
  const allowRemotePlugins = await fetchAllowRemotePlugins();

  try {
    const res = await fetch('/extensions/index.json', { cache: 'no-store' });
    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`);
    }
    const data = await res.json();
    
    if (!Array.isArray(data)) {
      throw new Error('index.json must be an array');
    }
    
    const entries: CatalogEntry[] = data
      .filter((item: any) => item && typeof item === 'object')
      .map((item: any) => ({
        id: String(item.id ?? ''),
        name: String(item.name ?? item.id ?? ''),
        version: String(item.version ?? '?'),
        manifestUrl: String(item.manifestUrl ?? ''),
        icon: typeof item.icon === 'string' ? item.icon : undefined,
        description: typeof item.description === 'string' ? item.description : undefined,
        origin: item.origin === 'registry' ? 'registry' : 'local',
      } satisfies CatalogEntry))
      .filter((e) => e.id && e.manifestUrl);
    
    catalog = { loading: false, error: null, entries, allowRemotePlugins };
    emitChange();
  } catch (e) {
    catalog = {
      loading: false,
      error: e instanceof Error ? e.message : String(e),
      entries: [],
      allowRemotePlugins,
    };
    emitChange();
  }
}

function getStatus(
  entry: CatalogEntry,
  installedPlugins: Array<{ manifestUrl: string; installedVersion?: string }>,
): CatalogStatus {
  const installed = installedPlugins.find(
    (p) => absoluteManifestUrl(p.manifestUrl) === absoluteManifestUrl(entry.manifestUrl),
  );
  if (!installed) {
    return { status: 'not-installed' };
  }
  if (!installed.installedVersion || installed.installedVersion === entry.version) {
    return {
      status: 'installed',
      installedVersion: installed.installedVersion,
      catalogVersion: entry.version,
    };
  }
  return {
    status: 'update-available',
    installedVersion: installed.installedVersion,
    catalogVersion: entry.version,
  };
}

function onChange(cb: () => void): () => void {
  changeListeners.add(cb);
  return () => {
    changeListeners.delete(cb);
  };
}

// initial fetch
refresh();

/** Относительный manifestUrl каталога → абсолютный (для записей settings и сверки). */
export function absoluteManifestUrl(u: string): string {
  try {
    return new URL(u, window.location.href).href;
  } catch {
    return u;
  }
}

export function useExtensionsCatalog() {
  return {
    get catalog() {
      return catalog;
    },
    getStatus,
    refresh,
    onChange,
  };
}

export type ExtensionsCatalog = ReturnType<typeof useExtensionsCatalog>;